def solve(inputs: dict) -> float:
    X = inputs['initial_value']
    steps = inputs['steps']

    # Mask to keep values within 32 bits
    MASK_32 = 0xFFFFFFFF

    for _ in range(steps):
        X ^= (X << 13) & MASK_32
        X ^= (X >> 7)
        X ^= (X << 15) & MASK_32
        X &= MASK_32

